// The Visual Studio 2013 (msvcr120) C runtime math functions that differ from other libms in the last bit, as portable
// software: a mechanical lift of the CRT's own x64 machine code (src/dotnet/vs2013_libm_gen.cpp, generated by
// tools/libm/gen_lift.py). Bit-exact with msvcr120_clr0400.dll on every host; used when the DLL is unavailable
// (non-Windows) or forced (CMake option KSP_LIBM_PORTABLE).
#pragma once

namespace ksp::dotnet::vs2013 {

double acos(double x);
double asin(double x);
double atan(double x);
double atan2(double y, double x);
double cosh(double x);
double exp(double x);
double log(double x);
double log10(double x);
double pow(double x, double y);
double sinh(double x);
double tan(double x);
double tanh(double x);

// The CRT picks FMA3 or SSE2 code paths at start-up (_set_FMA3_enable); the capture machine had FMA3 (default true).
void SetFma3(bool on);
bool GetFma3();

}  // namespace ksp::dotnet::vs2013
